{
  "tools": [
    {
      "name": "bridge_call",
      "title": "Native Call",
      "toolset": "bridge_helpers",
      "description": "Run any registered Bridge helper through the native connection. Use bridge_describe_handler first. Preserves the original play-mode guards and undo behaviour. Prefer dedicated native tools where available.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "command": {
            "type": "string",
            "description": "Exact command from bridge_list_handlers."
          },
          "parameters": {
            "type": "object",
            "description": "The helper's JSON parameters; omit for helpers with no arguments."
          }
        },
        "required": [
          "command"
        ]
      }
    },
    {
      "name": "bridge_describe_handler",
      "title": "Native Describe Handler",
      "toolset": "bridge_helpers",
      "description": "Read a Bridge handler's C# implementation to learn its parameters, defaults and behaviour. Searches every source file in this project's Bridge editor addon, including NPC and scaffold helpers.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "command": {
            "type": "string",
            "description": "Exact command from bridge_list_handlers."
          }
        },
        "required": [
          "command"
        ]
      },
      "annotations": {
        "readOnlyHint": true
      }
    },
    {
      "name": "bridge_list_handlers",
      "title": "Native List Handlers",
      "toolset": "bridge_helpers",
      "description": "List the live Bridge helpers, their read-only status and their play-mode restrictions. Use bridge_describe_handler to inspect arguments, then bridge_read or bridge_call.",
      "inputSchema": {
        "type": "object",
        "properties": {},
        "required": []
      },
      "annotations": {
        "readOnlyHint": true
      }
    },
    {
      "name": "bridge_read",
      "title": "Native Read",
      "toolset": "bridge_helpers",
      "description": "Run an allowlisted read-only Bridge helper directly inside the editor, without file IPC. Use bridge_describe_handler for parameters. Mutating commands are rejected.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "command": {
            "type": "string",
            "description": "Read-only command from bridge_list_handlers."
          },
          "parameters": {
            "type": "object",
            "description": "The helper's JSON parameters; omit for helpers with no arguments."
          }
        },
        "required": [
          "command"
        ]
      },
      "annotations": {
        "readOnlyHint": true
      }
    },
    {
      "name": "bridge_scatter_props",
      "title": "Native Scatter Props",
      "toolset": "bridge_helpers",
      "description": "Scatter model props with a repeatable seed, optional ground snapping, rotation, scaling and grouping. Requires stopped play mode. Uses the existing Bridge helper's scene and undo behaviour.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "model": {
            "type": "string",
            "description": "Project-relative model path, as returned by asset_search."
          },
          "center": {
            "type": "string",
            "description": "World-space centre as x,y,z, in Source units."
          },
          "radius": {
            "type": "number",
            "description": "Finite, nonnegative scatter radius in Source units.",
            "default": 256
          },
          "count": {
            "type": "integer",
            "description": "Number of props, from 1 to 300.",
            "default": 10
          },
          "seed": {
            "type": "integer",
            "description": "Nonnegative seed for repeatable placement.",
            "default": 1
          },
          "snapToGround": {
            "type": "boolean",
            "description": "Trace downward to place each prop on the ground.",
            "default": true
          },
          "randomYaw": {
            "type": "boolean",
            "description": "Randomise each prop's yaw.",
            "default": true
          },
          "scaleMin": {
            "type": "number",
            "description": "Positive minimum scale.",
            "default": 1
          },
          "scaleMax": {
            "type": "number",
            "description": "Maximum scale, at least scaleMin.",
            "default": 1
          },
          "group": {
            "type": "boolean",
            "description": "Parent the props under a new group object.",
            "default": true
          },
          "name": {
            "type": "string",
            "description": "Name prefix for the created objects.",
            "default": "Prop"
          }
        },
        "required": [
          "model",
          "center"
        ]
      }
    },
    {
      "name": "bridge_simulate_input",
      "title": "Native Simulate Input",
      "toolset": "bridge_helpers",
      "description": "Simulate a named input action during play. Press lasts one frame; hold is reapplied every frame; release ends a hold. A zero-duration hold continues until released. Requires play mode.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "action": {
            "type": "string",
            "description": "Input action name, for example jump, attack1 or attack2."
          },
          "state": {
            "type": "string",
            "description": "press, hold or release.",
            "default": "press"
          },
          "durationMs": {
            "type": "number",
            "description": "Nonnegative hold duration in milliseconds; zero holds until release.",
            "default": 0
          }
        },
        "required": [
          "action"
        ]
      }
    }
  ],
  "total": 128
}
